/** Reviews for one product, or null when there are none. */
export const reviewsForProduct = (slug) => {
  const r = mallcomReviews[slug];
  return r && r.count > 0 ? r : null;
};

export const productReviewCount = (slug) => mallcomReviews[slug]?.count || 0;
